{
    foreach (char c in wort)
    {
        if (!t.ContainsKey(c)) return false;
        t = (Dictionary<char, object>)t[c];
    }
    return t.ContainsKey('\0');
}

static IEnumerable<T[]> Permutationen<T>(T[] arr)
{
    if (arr.Length <= 1) { yield return arr; yield break; }
    foreach (var i in Enumerable.Range(0, arr.Length))
    {
        var rest = arr.Where((_, j) => j != i).ToArray();
        foreach (var p in Permutationen(rest))
            yield return arr[i..i+1].Concat(p).ToArray();
    }
}
